1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Item {
6	  type: string;
7	  material?: string;
8	  enchantment?: number;
9	  cursed?: boolean;
10	}
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Damage {
18	  itemType: string;
19	  amount: number;
20	}
21	
22	export interface ClaimStep {
23	  op: "claim";
24	  policy: number;
25	  incident: { cause: string; damages: Damage[] };
26	}
27	
28	export type Step = QuoteStep | ClaimStep;
29	
30	export interface Scenario {
31	  customer: Customer;
32	  steps: Step[];
33	}
34	
35	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
36	
37	export interface ScenarioResult {
38	  results: StepResult[];
39	}
40	
41	const PROCESSING_FEE = 5;
42	const FIRST_INSURANCE_SURCHARGE = 0.1;
43	
44	const SWORD_BASE_PREMIUM = 100;
45	const AMULET_BASE_PREMIUM = 60;
46	
47	/** Premiums are rounded in the MHPCO's favour: up to the next whole G. */
48	const roundUpToWholeG = (amount: number): number => Math.ceil(withoutFloatNoise(amount));
49	
50	/** Keeps binary floating-point drift from tipping an exact amount over a rounding boundary. */
51	const withoutFloatNoise = (amount: number): number => Number(amount.toFixed(6));
52	
53	/** Only sword and amulet prices are pinned down by the tests so far; other types follow. */
54	const basePremiumFor = (item: Item): number =>
55	  item.type === "amulet" ? AMULET_BASE_PREMIUM : SWORD_BASE_PREMIUM;
56	
57	const sum = (amounts: number[]): number => amounts.reduce((total, amount) => total + amount, 0);
58	
59	const premiumFor = (items: Item[]): number => {
60	  const basePremium = sum(items.map(basePremiumFor));
61	  return roundUpToWholeG(basePremium * (1 + FIRST_INSURANCE_SURCHARGE) + PROCESSING_FEE);
62	};
63	
64	export const runScenario = (scenario: Scenario): ScenarioResult => ({
65	  results: scenario.steps.map((step) => ({
66	    premium: premiumFor((step as QuoteStep).items),
67	  })),
68	});
